import{_ as s,o as i,c as t,a0 as e}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"配置文件","description":"","frontmatter":{},"headers":[],"relativePath":"config.md","filePath":"config.md","lastUpdated":null}'),n={name:"config.md"};function l(d,a,o,p,h,r){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to &quot;配置文件&quot;">​</a></h1><p>frp-sh 使用 TOML 配置文件（通过 <code>--config</code> 指定）。不指定时使用内置默认值（指向 <code>127.0.0.1</code>，仅供本机联调）。</p><h2 id="首次运行向导" tabindex="-1">首次运行向导 <a class="header-anchor" href="#首次运行向导" aria-label="Permalink to &quot;首次运行向导&quot;">​</a></h2><p>直接运行 <code>frp-sh</code>（不带参数）或 <code>frp-sh config</code> 可打开<strong>交互式配置向导</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  frp-sh 配置向导</span></span>
<span class="line"><span>  ==================</span></span>
<span class="line"><span>  1. 信令服务器地址 (HTTP) [默认 http://127.0.0.1:8080]</span></span>
<span class="line"><span>  &gt; http://101.43.41.195:8080</span></span>
<span class="line"><span>  2. 中继服务器地址 (TCP) [默认 101.43.41.195:8081]</span></span>
<span class="line"><span>  &gt;</span></span>
<span class="line"><span>  3. UDP 探测使用独立端口？(y/N)</span></span></code></pre></div><ul><li>地址可省略 <code>http://</code> 前缀（自动补全）</li><li>中继地址默认由信令地址推导（同主机 + 8081），直接回车即可</li><li>保存后自动做一次连通性检查（<code>/health</code>）</li><li>配置文件保存到平台默认位置，之后所有命令自动加载： <ul><li>Windows：<code>%APPDATA%\\frp-sh\\config.toml</code></li><li>Linux/macOS：<code>~/.config/frp-sh/config.toml</code></li></ul></li><li>重新配置：<code>frp-sh config</code>；也可用 <code>--config &lt;路径&gt;</code> 指定其他配置文件</li></ul><h2 id="配置字段" tabindex="-1">配置字段 <a class="header-anchor" href="#配置字段" aria-label="Permalink to &quot;配置字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>signaling_addr</code></td><td>否</td><td><code>http://127.0.0.1:8080</code></td><td>信令服务器 HTTP 基地址</td></tr><tr><td><code>relay_addr</code></td><td>否</td><td><code>127.0.0.1:8081</code></td><td>中继 TCP 地址</td></tr><tr><td><code>signaling_udp</code></td><td>否</td><td>与 HTTP 同端口</td><td>UDP 公网探测地址（独立端口时设置）</td></tr></tbody></table><h2 id="示例-连接远程服务器" tabindex="-1">示例：连接远程服务器 <a class="header-anchor" href="#示例-连接远程服务器" aria-label="Permalink to &quot;示例：连接远程服务器&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config/server.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_addr = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://101.43.41.195:8080&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">relay_addr     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;101.43.41.195:8081&quot;</span></span></code></pre></div><p>使用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/server.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/server.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game-a3f9c2</span></span></code></pre></div><h2 id="示例-独立-udp-探测端口" tabindex="-1">示例：独立 UDP 探测端口 <a class="header-anchor" href="#示例-独立-udp-探测端口" aria-label="Permalink to &quot;示例：独立 UDP 探测端口&quot;">​</a></h2><p>某些云防火墙要求 TCP 与 UDP 端口分开管理时使用：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_addr = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://101.43.41.195:8080&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">relay_addr     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;101.43.41.195:8081&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_udp  = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;101.43.41.195:8082&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # UDP 探测走 8082</span></span></code></pre></div><p>对应服务器侧需以 <code>--addr 0.0.0.0:8082</code> 单独提供 UDP 探测（或自行部署兼容端点）。</p><h2 id="字段说明" tabindex="-1">字段说明 <a class="header-anchor" href="#字段说明" aria-label="Permalink to &quot;字段说明&quot;">​</a></h2><h3 id="signaling-addr" tabindex="-1">signaling_addr <a class="header-anchor" href="#signaling-addr" aria-label="Permalink to &quot;signaling_addr&quot;">​</a></h3><p>REST API 基地址：</p><ul><li><code>POST /room/create</code> — 注册房间</li><li><code>GET /room/{id}</code> — 查询房间</li><li><code>POST /room/{id}/join</code> — 访客登记</li><li><code>DELETE /room/{id}</code> — 关闭房间</li></ul><h3 id="signaling-udp" tabindex="-1">signaling_udp <a class="header-anchor" href="#signaling-udp" aria-label="Permalink to &quot;signaling_udp&quot;">​</a></h3><p>UDP 公网探测端点：客户端发送 <code>ECHO &lt;token&gt;</code>，服务端回 <code>ADDR &lt;token&gt; &lt;ip&gt;:&lt;port&gt;</code>，客户端由此得知自己经 NAT 映射后的公网地址。</p><blockquote><p>探测必须使用<strong>与打洞相同的 socket</strong>（同一本地端口），保证通告的地址就是打洞可用的映射。</p></blockquote><h3 id="relay-addr" tabindex="-1">relay_addr <a class="header-anchor" href="#relay-addr" aria-label="Permalink to &quot;relay_addr&quot;">​</a></h3><p>打洞失败时的 TCP 中继端点。连接后发送 <code>HELLO &lt;room_id&gt; &lt;HOST|GUEST&gt;</code> 完成配对。</p><h2 id="配置优先级" tabindex="-1">配置优先级 <a class="header-anchor" href="#配置优先级" aria-label="Permalink to &quot;配置优先级&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>命令行参数 &gt; 配置文件 &gt; 内置默认值</span></span></code></pre></div><p>当前 CLI 中，<code>serve</code> 的监听地址仅由命令行参数控制；客户端地址由配置文件控制。</p>`,28)])])}const k=s(n,[["render",l]]);export{g as __pageData,k as default};
